        formulas: [["Fₜ₊₁ = Fₜ + α·(Aₜ − Fₜ)", "suavização exponencial"], ["MAD = Σ|eₜ| ÷ n", "desvio absoluto médio"], ["TS = Σeₜ ÷ MAD", "sinal de rastreamento"]],
